#!/usr/bin/env ruby
require'digest';require'json';require'fileutils';root=File.expand_path('..',__dir__);patterns=%w[server/*/target/*.jar deploy/* database/migrations/*.sql docs/generated/generated-artifact-manifest.json];files=patterns.flat_map{|p|Dir.glob(File.join(root,p))}.select{|p|File.file?(p)}.sort;dir=File.join(root,'work/release');FileUtils.mkdir_p(dir);sum=File.join(dir,'SHA512SUMS');File.write(sum,files.map{|p|"#{Digest::SHA512.file(p).hexdigest}  #{p.delete_prefix(root+'/')}"}.join("\n")+"\n");tool=File.read(File.join(root,'tools/sign-release-artifacts.sh'));checks={artifactsInventoried:!files.empty?,sha512Manifest:File.size(sum)>0,explicitKeyInjection:tool.include?('AOO_RELEASE_SIGNING_KEY')&&tool.include?('AOO_RELEASE_VERIFY_KEY'),signatureVerification:tool.include?('openssl dgst -sha512 -verify'),signaturePresent:File.file?(sum+'.sig')};report={schemaVersion:1,artifactCount:files.length,checksumManifest:'work/release/SHA512SUMS',checks:checks,verdict:checks[:signaturePresent] ? 'passed':'awaiting-approved-signing-key'};out=File.join(root,'docs/generated/build08-artifact-signing.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(report)+"\n");puts "BUILD08 AUDITED: #{report[:verdict]}"
